# L1: 最小化出处生成
name: SLSA L1 Build

on:
  push:
    tags: ['v*']

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Build
        id: build
        run: |
          make build
          sha256sum ./dist/myapp > ./dist/myapp.sha256

      - name: Generate L1 Provenance
        run: |
          cat > provenance.json << EOF
          {
            "_type": "https://in-toto.io/Statement/v0.1",
            "predicateType": "https://slsa.dev/provenance/v1",
            "subject": [{
              "name": "myapp",
              "digest": {
                "sha256": "$(sha256sum ./dist/myapp | awk '{print $1}')"
              }
            }],
            "predicate": {
              "buildDefinition": {
                "buildType": "https://github.com/actions/runner@v2",
                "externalParameters": {
                  "workflow": "${{ github.workflow }}",
                  "ref": "${{ github.ref }}"
                }
              },
              "runDetails": {
                "builder": {
                  "id": "https://github.com/actions/runner"
                },
                "metadata": {
                  "invocationID": "${{ github.run_id }}/${{ github.run_attempt }}",
                  "startedOn": "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
                }
              }
            }
          }
          EOF

      - name: Upload artifacts
        uses: actions/upload-artifact@v4
        with:
          name: myapp-${{ github.ref_name }}
          path: |
            ./dist/myapp
            ./dist/myapp.sha256
            ./provenance.json

